import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第六十卦 節 水澤節 坎上兌下","description":"周易 - 第六十卦 節 水澤節 坎上兌下","frontmatter":{"title":"第六十卦 節 水澤節 坎上兌下","description":"周易 - 第六十卦 節 水澤節 坎上兌下"},"headers":[],"relativePath":"classics/zhouyi/061.md","filePath":"classics/zhouyi/061.md"}'),l={name:"classics/zhouyi/061.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="節" tabindex="-1">節 <a class="header-anchor" href="#節" aria-label="Permalink to “節”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨。苦節不可貞。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>節，亨，剛柔分，而剛得中。苦節不可貞，其道窮也。說以行險，當位以節，中正以通。天地節而四時成，節以制度，不傷財，不害民。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>澤上有水，節；君子以制數度，議德行。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>不出戶庭，無咎。象曰：不出戶 庭，知通塞也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>不出門庭，兇。象曰：不出門庭，失時極也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>不節若，則嗟若，無咎。象曰：不節之嗟，又誰咎也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>安節，亨。象曰：安節之亨，承上道也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>甘節，吉；往有尚。象曰：甘節之吉，居位中也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>苦節，貞兇，悔亡。象曰：苦節貞兇，其道窮也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
